const eventTypesStyles = `
  .event-types {
    width: 100%;
    padding: 12px 20px 14px;
    box-sizing: border-box;
    background: #fff;
    color: #164b70;
    font-family: Arial, Helvetica, sans-serif;
  }

  .event-types__title {
    margin: 0 0 12px;
    font-size: 11px;
    line-height: 1.2;
    font-weight: 700;
    text-transform: uppercase;
  }

  .event-types__list {
    display: grid;
    grid-template-columns: repeat(8, minmax(0, 1fr));
    align-items: start;
    gap: 8px;
  }

  .event-types__item {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    gap: 7px;
    min-width: 0;
    text-align: center;
  }

  .event-types__icon {
    width: 34px;
    height: 34px;
    flex-shrink: 0;
    fill: none;
    stroke: #164b70;
    stroke-width: 1.8;
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  .event-types__label {
    display: flex;
    flex-direction: column;
    align-items: center;
    font-size: 10px;
    line-height: 1.35;
    font-weight: 500;
  }

  @media (max-width: 700px) {
    .event-types__list {
      grid-template-columns: repeat(4, minmax(0, 1fr));
      row-gap: 20px;
    }
  }

  @media (max-width: 380px) {
    .event-types {
      padding-left: 12px;
      padding-right: 12px;
    }

    .event-types__icon {
      width: 29px;
      height: 29px;
    }

    .event-types__label {
      font-size: 9px;
    }
  }
`;

(function() {
    if (document.getElementById('ic-event-types-styles')) return;

    const tag = document.createElement('style');
    tag.id = 'ic-event-types-styles';
    tag.textContent = eventTypesStyles;
    document.head.appendChild(tag);
})();

// Imagen PNG del icono "drama" (eventos culturales) en base64.
// Pegá el base64 completo en lugar de PEGAR_BASE64_AQUI (sin saltos de línea).
const DRAMA_ICON_SRC = 'data:image/png;base64,\n' +
    '\n';

export default {
    name: 'EventTypes',

    props: {
        titulo: {
            type: String,
            default: 'TIPOS DE EVENTOS'
        },
        items: {
            type: Array,
            default: () => [
                { titulo: 'Eventos', subtitulo: 'culturales', icono: 'drama' },
                { titulo: 'Exposiciones', subtitulo: 'y ferias', icono: 'users' },
                { titulo: 'Eventos', subtitulo: 'corporativos', icono: 'building' },
                { titulo: 'Desfiles', subtitulo: 'y moda', icono: 'dress' },
                { titulo: 'Museos y', subtitulo: 'galerías', icono: 'gallery' },
                { titulo: 'Presentaciones', subtitulo: 'inmobiliarias', icono: 'house' },
                { titulo: 'Subastas', subtitulo: '', icono: 'gavel' },
                { titulo: 'Producciones', subtitulo: 'especiales', icono: 'calendar' }
            ]
        }
    },

    methods: {
        iconSvg(icono) {
            const icons = {
                // Imagen en lugar de paths: se centra y escala dentro del viewBox 24x24
                drama: `
          <image href="${DRAMA_ICON_SRC}" x="0" y="0" width="24" height="24" preserveAspectRatio="xMidYMid meet"/>
        `,
                users: `
          <circle cx="12" cy="7" r="3"/>
          <path d="M6 20v-2a6 6 0 0 1 12 0v2z"/>
          <circle cx="5" cy="10" r="2"/>
          <circle cx="19" cy="10" r="2"/>
          <path d="M2 18v-1a4 4 0 0 1 4-4M22 18v-1a4 4 0 0 0-4-4"/>
        `,
                building: `
          <rect x="5" y="2" width="14" height="20" rx="1"/>
          <path d="M9 6h1M14 6h1M9 10h1M14 10h1M9 14h1M14 14h1M11 22v-4h2v4"/>
        `,
                dress: `
          <path d="M9 3l3 2 3-2 4 4-3 4 2 11H6L8 11 4 7z"/>
          <path d="M8 11h8"/>
        `,
                gallery: `
          <rect x="2" y="3" width="20" height="18" rx="1"/>
          <circle cx="8" cy="8" r="2"/>
          <path d="M2 17l6-6 4 4 3-3 7 7"/>
        `,
                house: `
          <path d="M3 10L12 3l9 7"/>
          <path d="M5 9v12h14V9M10 21v-7h4v7"/>
          <path d="M19 3v4"/>
        `,
                gavel: `
<path d="m14.5 12.5-8 8a2.119 2.119 0 1 1-3-3l8-8"/>
<path d="m16 16 6-6"/>
<path d="m8 8 6-6"/>
<path d="m9 7 8 8"/>
<path d="m21 11-8-8"/>
`,
                calendar: `
          <rect x="3" y="5" width="18" height="16" rx="2"/>
          <path d="M16 3v4M8 3v4M3 10h18"/>
          <path d="M8 14h2M14 14h2M8 17h2"/>
        `
            };

            return icons[icono] || icons.gallery;
        }
    },

    template: `
    <section class="event-types">
      <h2 class="event-types__title">{{ titulo }}</h2>
      <div class="event-types__list">
        <div
          v-for="(item, i) in items"
          :key="i"
          class="event-types__item"
        >
          <svg
            class="event-types__icon"
            viewBox="0 0 24 24"
            xmlns="http://www.w3.org/2000/svg"
            aria-hidden="true"
            v-html="iconSvg(item.icono)"
          ></svg>

          <span class="event-types__label">
            <span>{{ item.titulo }}</span>
            <span v-if="item.subtitulo">{{ item.subtitulo }}</span>
          </span>
        </div>
      </div>
    </section>
  `
};